// NewListResponseBody builds the HTTP response body from the result of the
// "list" endpoint of the "notes" service.
func NewListResponseBody(res *notes.NoteList) *ListResponseBody {
	body := &ListResponseBody{
		Total: res.Total,
	}
	if res.Notes != nil {
		body.Notes = make([]*NoteSummaryResponseBody, len(res.Notes))
		for i, val := range res.Notes {
			if val == nil {
				body.Notes[i] = nil
				continue
			}
			body.Notes[i] = marshalNotesNoteSummaryToNoteSummaryResponseBody(val)
		}
	} else {
		body.Notes = []*NoteSummaryResponseBody{}
	}
	if res.Separators != nil {
		body.Separators = make([]*SeparatorResponseBody, len(res.Separators))
		for i, val := range res.Separators {
			if val == nil {
				body.Separators[i] = nil
				continue
			}
			body.Separators[i] = marshalNotesSeparatorToSeparatorResponseBody(val)
		}
	}
	return body
}

// NewGetResponseBody builds the HTTP response body from the result of the
// "get" endpoint of the "notes" service.
func NewGetResponseBody(res *notes.Note) *GetResponseBody {
	body := &GetResponseBody{
		ID:              res.ID,
		Notebook:        res.Notebook,
		Title:           res.Title,
		CreatedAt:       res.CreatedAt,
		UpdatedAt:       res.UpdatedAt,
		TrashedNotebook: res.TrashedNotebook,
		CreatedBy:       res.CreatedBy,
		Archived:        res.Archived,
		Body:            res.Body,
		TrashedFrom:     res.TrashedFrom,
		ArchivedAt:      res.ArchivedAt,
	}
	if res.Tags != nil {
		body.Tags = make([]string, len(res.Tags))
		for i, val := range res.Tags {
			body.Tags[i] = val
		}
	} else {
		body.Tags = []string{}
	}
	if res.Marks != nil {
		body.Marks = make([]string, len(res.Marks))
		for i, val := range res.Marks {
			body.Marks[i] = val
		}
	}
	if res.TitleHighlights != nil {
		body.TitleHighlights = make([]*TextRangeResponseBody, len(res.TitleHighlights))
		for i, val := range res.TitleHighlights {
			if val == nil {
				body.TitleHighlights[i] = nil
				continue
			}
			body.TitleHighlights[i] = marshalNotesTextRangeToTextRangeResponseBody(val)
		}
	}
	if res.BodyHighlights != nil {
		body.BodyHighlights = make([]*TextRangeResponseBody, len(res.BodyHighlights))
		for i, val := range res.BodyHighlights {
			if val == nil {
				body.BodyHighlights[i] = nil
				continue
			}
			body.BodyHighlights[i] = marshalNotesTextRangeToTextRangeResponseBody(val)
		}
	}
	return body
}

